/* First-paint boot for the table intro screen.
   Plain synchronous script: runs during HTML parsing, long before the module graph.
   The intro copy and an inline cover are already final on the very first frame. */
(function(){
  'use strict';
  var COVERS={"four":"data:image/webp;base64,","gomoku":"data:image/webp;base64,","chess":"data:image/webp;base64,","puzzle":"data:image/webp;base64,","draw":"data:image/webp;base64,","cards":"data:image/webp;base64,","pool":"data:image/webp;base64,","snooker":"data:image/webp;base64,","bubbles":"data:image/webp;base64,","xo":"data:image/webp;base64,"};
  var DATA={"four":{"zh":"四子连珠","en":"Connect Four","desc":"7 列棋盘，轮流选一列落子，棋子堆到该列最下方。先横、竖或斜连成 4 颗获胜。","instruction":"点击左侧任意一列落子。横、竖或斜向连成四颗就能获胜。","rules":"轮流选择一列落子，棋子落到该列最下方的空位。横、竖或斜向连成4颗即获胜。"},"gomoku":{"zh":"五子棋","en":"Gomoku","desc":"黑白轮流落子，先连成 5 颗获胜。当前为无禁手规则。","instruction":"点击棋盘空位落子。连成五颗及以上获胜，当前采用无禁手规则。","rules":"双方轮流落子，黑棋先行。横、竖或斜向连成5颗及以上获胜；当前为无禁手的自由五子棋。"},"chess":{"zh":"国际象棋","en":"Chess","desc":"标准国际象棋，白棋先行。支持王车易位、吃过路兵与升变，将死获胜。","instruction":"先选自己的棋子，再选目标格。白棋先行，支持王车易位、吃过路兵和升变。","rules":"白棋先行。点击自己的棋子，再点击目标格。支持王车易位、吃过路兵及升变；将死获胜，逼和、重复局面、50回合及子力不足判和。电脑为基础难度。"},"puzzle":{"zh":"趣味拼图","en":"Puzzles","desc":"交换两块图片还原画面，可与好友轮流协作，也支持拖动交换。","instruction":"先选一块图片，再选另一块交换。也可以拖动交换位置。","rules":"交换两块拼图，还原完整的飞行棋画面。点击两块图片交换位置，也可以拖动交换。联机时与好友轮流协作；完成后两人各+3分。","score":"登录账号的联机合作成果自动保存，每位参与者各+3分；单机和游客对局不累计。","computer":"单机 · 电脑协作"},"draw":{"zh":"你画我猜","en":"Draw & Guess","desc":"两人轮流画画与猜词，共 6 题，按猜对次数计分。","instruction":"画题的一方在画布上作画，另一方输入答案。共六题，猜对就进入下一题。","rules":"两人轮流画画与猜词，共6题。猜对者得2题分，画画者得1题分；每题最多6次，猜题间隔1秒；最终按题分排名结算。单机电脑出图为几何图形练习，不模拟真人猜词。","computer":"单机 · 电脑出图"},"cards":{"zh":"欢乐纸牌","en":"Cards","desc":"两人各 7 张牌，按颜色或数字接龙，先出完手牌获胜。","instruction":"选择与桌面牌同色或同数字的手牌。也可以摸一张并结束回合。","rules":"颜色数字接龙：两人各7张，轮流打出与桌面同色或同数字的牌，也可摸一张并结束回合。先出完手牌获胜。没有功能牌、不下注；牌库耗尽时重洗弃牌。"},"pool":{"zh":"欢乐台球","en":"Pool","desc":"休闲八球：瞄准、蓄力、击球。先清空本组球，再合法打进 8 号获胜。","instruction":"点击球桌选择方向，再调整力度击球。先清空1–7号共享目标，再合法打进8号。","rules":"休闲台球：移动鼠标瞄准，按住左键锁定方向，向后拖动蓄力，松开击球。左上角白球可选择击球点。首次有效进球确定全色（1–7）或花色（9–15），打进本组球可继续击球；分组后先碰对方球、未先碰本组目标球，或白球落袋，均为犯规。犯规后对手获得额外一杆，白球落袋自动复位。清空本组后下一杆打进8号获胜，提前打进8号或同时白球落袋判负。最多200杆后按落袋数判定。此模式不是完整竞技八球规则。"},"snooker":{"zh":"斯诺克","en":"Snooker","desc":"两人轮流击球，红球与彩球交替，最后按分值顺序清彩。可挑战电脑或联网对战。","instruction":"轮到你时瞄准并向后拖动蓄力，松手击球。红球和彩球交替击打，最后按分值顺序清彩。","rules":"两人轮流击球：先打红球，再打彩球，红球清空后按分值顺序清彩；得分高者获胜。可挑战电脑或联网对战。"},"bubbles":{"zh":"泡泡射击","en":"Bubble Shooter","desc":"两人轮流发射，三个及以上同色泡泡相连即可消除；24 回合后得分高者获胜。可挑战电脑或联网对战。","instruction":"轮到你时移动鼠标瞄准，点击发射。三个及以上同色泡泡相连即可消除，24 回合后比分高者获胜。","rules":"两人轮流在同一块球阵上发射。三个或更多同色泡泡相连即可消除，悬空泡泡掉落另有加分；未消除累计 5 次，球阵下压一行。清空球阵额外 +2000 分；球阵触线或打满 24 回合即结算，比分高者获胜。","computer":"单机 · 电脑对战"},"xo":{"zh":"井字棋","en":"Tic-tac-toe","desc":"3×3 棋盘，双方轮流放 X 或 O，先连成一条线获胜。","instruction":"横、竖或斜线连成三个同样的符号即可获胜。","rules":"横、竖或斜线连成三个同样的符号即可获胜。","xo":true}};
  /* Demo standings: a freshly deployed site has no completed online matches,
     so the board is filled on the very first frame. Real rows always win. */
  var DEMO_PLAYERS=[
    {name:'Ava Mitchell',avatar:0,member:true,annual:true,points:[486,132,28],games:[96,27,6]},
    {name:'Leo Park',avatar:1,member:true, points:[452,118,24],games:[91,24,5]},
    {name:'Mia Chen',avatar:2,member:false,points:[418,105,21],games:[88,22,5]},
    {name:'Noah Kim',avatar:3,member:false,points:[386,96,18], games:[82,20,4]},
    {name:'Zoe Walker',avatar:0,member:true, points:[351,87,16], games:[78,18,4]},
    {name:'Kai Nakamura',avatar:1,member:false,points:[312,74,14], games:[71,16,3]},
    {name:'Iris Dubois',avatar:2,member:false,points:[278,66,12], games:[66,14,3]},
    {name:'Evan Silva',avatar:3,member:false,points:[231,55,10], games:[59,12,2]},
    {name:'Nora Bennett',avatar:0,member:false,points:[184,43,8],  games:[51,10,2]},
    {name:'Sam Rivera',avatar:1,member:false,points:[142,32,6],  games:[43,8,1]}
  ];
  var PERIODS=['month','week','day'];
  window.__joyflockDemoRows=function(period,game){
    var p=Math.max(0,PERIODS.indexOf(period)),shift=(game||'').length%3;
    return DEMO_PLAYERS.map(function(d,i){
      /* A small per-game scale keeps the demo numbers distinct without
         ever producing a negative score on the short daily board. */
      var factor=1-shift*0.02*i;
      return {name:d.name,points:Math.max(2,Math.round(d.points[p]*factor)),games:d.games[p],
        avatarUrl:'/api/avatars/system/'+d.avatar,member:d.member,annualMember:!!d.annual,
        frame:d.member?'gold':''};
    });
  };
  /* Shared row builder: the boot script and table.js produce identical markup,
     so the async leaderboard refresh never changes the board's height. */
  window.__joyflockRankRow=function(doc,row,index){
    var li=doc.createElement('li');
    var rank=doc.createElement('span');rank.className='rank-medal rank-'+(index+1);
    rank.textContent=String(index+1).padStart(2,'0');
    var seat=doc.createElement('div');seat.className='seat'+(row.member?' member':'');
    var shell=doc.createElement('span');shell.className='avatar-shell';
    var img=doc.createElement('img');img.className='seat-avatar';img.alt='';
    img.src=row.avatarUrl||'/api/avatars/system/'+(index%4);shell.append(img);
    var copy=doc.createElement('div');copy.className='seat-copy';
    var line=doc.createElement('div');line.className='seat-name';
    var name=doc.createElement('strong');name.textContent=row.name||'玩家';line.append(name);
    if(row.member){var annual=row.member&&row.annualMember===true;
      var badge=doc.createElement('span');badge.className='member-label'+(annual?' annual':'');
      badge.setAttribute('role','img');badge.setAttribute('aria-label',annual?'Annual VIP':'VIP');line.append(badge);}
    copy.append(line);seat.append(shell,copy);
    var points=doc.createElement('b');points.className='ranking-points';points.textContent=row.points;
    var games=doc.createElement('span');games.className='ranking-games';games.textContent=row.games;
    li.append(rank,seat,points,games);return li;
  };
  window.__joyflockDemoBoard=function(lb,period,game){
    if(!lb)return;
    var doc=lb.ownerDocument,rows=window.__joyflockDemoRows(period,game);
    lb.replaceChildren.apply(lb,rows.map(function(r,i){return window.__joyflockRankRow(doc,r,i);}));
  };
  window.__joyflockDemoStats=function(locale){
    return (locale||document.documentElement.getAttribute('data-locale'))==='en'
      ?'My record: 278 pts · 66 games · +36 this month'
      :'我的战绩：278 积分 · 66 局 · 本月 +36 分';
  };
  var VALID=['four','gomoku','chess','puzzle','draw','cards','pool','snooker','bubbles','xo'];
  var g=new URLSearchParams(location.search).get('game');
  if(VALID.indexOf(g)<0)g='four';
  var d=DATA[g],r=document.documentElement;
  r.setAttribute('data-game',g);
  document.title=((r.getAttribute('data-locale')==='en'?d.en:d.zh)+' · JoyFlock');
  window.__INTRO_GAME=g;
  window.__fillIntro=function(){
    var $=function(id){return document.getElementById(id);};
    var hide=function(el){if(el)el.hidden=true;};
    var img=$('hero-image');
    if(img){
      img.src=COVERS[g];img.alt=d.zh+' 游戏插画';
      /* The inline cover is a 192px thumbnail: perfect for a stable first
         frame, but soft once the detail view shows it at ~260px. Load the
         full-size cover after the page has painted, decode it off-screen and
         swap only when it is ready. Same artwork, so nothing flashes -- the
         picture just becomes sharp. */
      if(!img.getAttribute('data-cover-hd')){
        img.setAttribute('data-cover-hd','1');
        var upgrade=function(){
          if(!img.isConnected||img.getAttribute('src')!==COVERS[g])return;
          var file='/assets/covers/'+g+(g==='xo'?'.svg':'.jpg');
          var hd=new Image();hd.decoding='async';
          var swap=function(){
            if(img.isConnected&&img.getAttribute('src')===COVERS[g])img.src=file;
          };
          hd.onload=function(){if(hd.decode)hd.decode().then(swap,swap);else swap();};
          hd.src=file;
        };
        if(document.readyState==='complete')setTimeout(upgrade,0);
        else window.addEventListener('load',function(){setTimeout(upgrade,0);},{once:true});
      }
    }
    $('hero-kicker').textContent=d.en;
    $('hero-title').textContent=d.zh;
    $('hero-description').textContent=d.desc;
    $('game-name').textContent=d.zh;
    $('turn-instruction').textContent=d.instruction;
    $('rules').textContent=d.rules;
    if(d.score)$('score-note').textContent=d.score;
    if(d.computer)$('computer').textContent=d.computer;
    /* Local two-player retired: no #local button is rendered. */
    var lb=$('leaderboard');
    if(lb&&!lb.children.length)window.__joyflockDemoBoard(lb,'month',g);
    var st=$('stats');if(st&&!st.textContent)st.textContent=window.__joyflockDemoStats();
    /* Tic-tac-toe is a hosted room game now: keep Quick play / Create room /
       Join and the leaderboard visible, exactly like Pool. Only the single
       player arcade titles hide those controls. */
    if(d.arcade){
      hide($('quick'));hide($('friends'));hide($('join-open'));hide($('score-note'));
    }
    if(d.arcade){
      if(d.arcade)$('computer').classList.add('primary');
      var rank=document.querySelector('.home-ranking');
      if(rank){
        rank.querySelector('.ranking-heading h2').textContent='游戏模式';
        ['.period-tabs','.ranking-columns','#leaderboard','.ranking-footnote','#stats'].forEach(function(s){hide(rank.querySelector(s));});
        var info=document.createElement('p');info.textContent=d.arcadeInfo;rank.append(info);
      }
      if(d.solo){var first=document.querySelector('.hero-tags span');if(first)first.textContent='1位玩家';$('player-count').textContent='1位参与';}
    }
    document.documentElement.setAttribute('data-intro-ready','1');
  };
})();
